#include "melodee/shell/harmony_tool.h"
#include <cassert>
#include <iostream>
using namespace melodee;
int main(){HarmonyTool h;h.scale_choice=7;h.mode=2;h.wav_track=4;h.wav_pad=99;h.midi_track=7;h.midi_pattern=3;h.midi_read=1;h.midi_pad=126;h.bars=8;h.settings.genre=22;h.settings.variation=999;h.parts.output=4;h.parts.hybrid_rhythm=11;h.parts.melody.variation=999;h.parts.melody.gate=67;h.parts.melody.octave=2;auto saved=harmony_setup(h);assert(saved.used);HarmonyTool restored;restore_harmony_setup(restored,saved);assert(restored.scale_choice==7&&restored.mode==2&&restored.wav_track==4&&restored.wav_pad==99&&restored.midi_track==7&&restored.midi_pattern==3&&restored.midi_read==1&&restored.midi_pad==126&&restored.parts.output==4&&restored.parts.hybrid_rhythm==11&&restored.parts.melody.gate==67&&restored.settings.genre==22&&restored.parts.genre==22);vary_harmony_setup(restored);assert(restored.settings.variation==0&&restored.parts.melody.variation==0&&restored.stale);assert(saved.settings.variation==999&&saved.parts.melody.variation==999);assert(restored.wav_track==saved.wav_track&&restored.wav_pad==saved.wav_pad&&restored.parts.hybrid_rhythm==11);harmony_step_begin(restored,3);assert(restored.step==3&&restored.row==31&&restored.choice==0);std::cout<<"Last-setup snapshot/restore, independent state, bounded alternatives and direct Preview entry passed.\n";}
